import json
with open('baseline-packages.json') as f: b = json.load(f)
with open('after-cpm-packages.json') as f: a = json.load(f)

def get_pkgs(data):
    result = {}
    for proj in data.get('projects', []):
        pname = proj['path'].split('/')[-1]
        pkgs = {}
        for fw in proj.get('frameworks', []):
            for pkg in fw.get('topLevelPackages', []):
                pkgs[pkg['id']] = pkg.get('resolvedVersion', pkg.get('requestedVersion','?'))
        result[pname] = pkgs
    return result

bp = get_pkgs(b)
ap = get_pkgs(a)

changes = []
unchanged = []
for proj in sorted(set(list(bp.keys()) + list(ap.keys()))):
    for pkg in sorted(set(list(bp.get(proj,{}).keys()) + list(ap.get(proj,{}).keys()))):
        bv = bp.get(proj,{}).get(pkg)
        av = ap.get(proj,{}).get(pkg)
        if bv != av:
            changes.append((proj, pkg, bv or 'N/A', av or 'N/A'))
        else:
            unchanged.append((proj, pkg, bv))

print('=== CHANGES ===')
for c in changes:
    print(f'{c[0]:20s} {c[1]:40s} {c[2]:12s} -> {c[3]}')
print()
print('=== UNCHANGED ===')
for u in unchanged:
    print(f'{u[0]:20s} {u[1]:40s} {u[2]}')
"

